<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Order\\State;\n\ninterface OrderStateInterface\n{\n    public function handle(OrderProcessor $processor): void;\n    public function getStatus(): string;\n}\n\nclass PendingState implements OrderStateInterface\n{\n    public function handle(OrderProcessor $processor): void\n    {\n        // Validate order data\n        if (empty($processor->order['items'])) {\n            throw new \\RuntimeException('Order must have items');\n        }\n        $processor->order['status'] = 'pending';\n        $processor->order['pending_at'] = date('Y-m-d H:i:s');\n    }\n\n    public function getStatus(): string\n    {\n        return 'pending';\n    }\n}\n\nclass ProcessingState implements OrderStateInterface\n{\n    public function handle(OrderProcessor $processor): void\n    {\n        $processor->order['status'] = 'processing';\n        $processor->order['processing_at'] = date('Y-m-d H:i:s');\n        // Notify fulfillment system\n    }\n\n    public function getStatus(): string\n    {\n        return 'processing';\n    }\n}\n\nclass ShippedState implements OrderStateInterface\n{\n    public function handle(OrderProcessor $processor): void\n    {\n        $processor->order['status'] = 'shipped';\n        $processor->order['shipped_at'] = date('Y-m-d H:i:s');\n        // Generate tracking number placeholder\n    }\n\n    public function getStatus(): string\n    {\n        return 'shipped';\n    }\n}\n\nclass DeliveredState implements OrderStateInterface\n{\n    public function handle(OrderProcessor $processor): void\n    {\n        $processor->order['status'] = 'delivered';\n        $processor->order['delivered_at'] = date('Y-m-d H:i:s');\n        // Mark as complete\n    }\n\n    public function getStatus(): string\n    {\n        return 'delivered';\n    }\n}\n\nclass OrderProcessor\n{\n    public array $order;\n    private OrderStateInterface $state;\n\n    public function setState(OrderStateInterface $state): void\n    {\n        $this->state = $state;\n    }\n\n    public function handleState(): void\n    {\n        $this->state->handle($this);\n    }\n}
